 * @param e - Optional RSA exponent to check against the prime
 * @param k - Optional number of iterations of Miller-Rabin test
 */
export function isProbablePrime(n: bigint, e: bigint, k: number) {
  if (e && gcd(n - _1n, e) !== _1n) {
    return false;
